module msrv_soc_zbc(A, RevA, B, Funct3, ZBCResult);
  input  [63:0] A, RevA, B;
  input  [1:0] Funct3;
  output [63:0] ZBCResult;

  wire [63:0] ClmulResult, RevClmulResult, RevB, X, Y;
  wire [1:0] rtlcn1;
  wire rtlcClkX, rtlcXXX;
  supply0 rtlcVss;
  supply1 rtlcVcc;

  msrv_soc_bitreverse brB(
      .A(B), .RevA(RevB)
  );
  msrv_soc_mux2 ymux(
      .d0(B), .d1(RevB), .s(Funct3[1]), .y(Y)
  );
  msrv_soc_clmul clm(
      .X(X), .Y(Y), .ClmulResult(ClmulResult)
  );
  msrv_soc_bitreverse brClmulResult(
      .A(ClmulResult), .RevA(RevClmulResult)
  );
  msrv_soc_mux2 zbcresultmux(
      .d0(ClmulResult), .d1(RevClmulResult), .s(Funct3[1]), .y(ZBCResult)
  );
  msrv_soc_mux3_pv1 \genblk1.xmux (
      .d0({RevA[62:0], 1'b0}), .d1(RevA), .d2(A), .s(rtlcn1), .y(X)
  );
  RTLC_INV rtlc0_66(
      .Z(rtlcn1[0]), .A(Funct3[0])
  );
  RTLC_INV rtlc0_67(
      .Z(rtlcn1[1]), .A(Funct3[1])
  );
endmodule

