module msrv_soc_cnt(A, RevA, B, W64, CntResult);
  input  [63:0] A, RevA;
  input  [1:0] B;
  input  W64;
  output [63:0] CntResult;

  wire [63:0] czResult, cpopResult, lzcA, popcntA;
  wire rtlcClkX, rtlcXXX;
  supply0 rtlcVss;
  supply1 rtlcVcc;

  msrv_soc_lzc lzc(
      .num(lzcA), .ZeroCnt(czResult[6:0])
  );
  msrv_soc_popcnt popcntw(
      .num(popcntA), .PopCnt(cpopResult[6:0])
  );
  msrv_soc_mux2 cntresultmux(
      .d0(czResult), .d1(cpopResult), .s(B[1]), .y(CntResult)
  );
  msrv_soc_mux4_pv2 \genblk1.lzcmux64 (
      .d0(A), .d1({A[31:0], 32'b11111111111111111111111111111111}), .d2(RevA), 
      .d3({RevA[63:32], 32'b11111111111111111111111111111111}), .s({B[0], 
      W64}), .y(lzcA)
  );
  msrv_soc_mux2 \genblk1.popcntmux64 (
      .d0(A), .d1({32'b00000000000000000000000000000000, A[31:0]}), .s(W64), .y(popcntA)
  );
  RTLC_BUF rtlc0_194(
      .Z(czResult[7]), .A(1'b0)
  );
  RTLC_BUF rtlc0_195(
      .Z(czResult[8]), .A(1'b0)
  );
  RTLC_BUF rtlc0_196(
      .Z(czResult[9]), .A(1'b0)
  );
  RTLC_BUF rtlc0_197(
      .Z(czResult[10]), .A(1'b0)
  );
