module msrv_soc_zbb(A, RevA, B, W64, LT, LTU, BUnsigned, ZBBSelect, ZBBResult);
  input  [63:0] A, RevA, B;
  input  [2:0] ZBBSelect;
  input  W64, LT, LTU, BUnsigned;
  output [63:0] ZBBResult;

  wire [63:0] CntResult, MinMaxResult, ByteResult, ExtResult;
  wire [1:0] rtlcn0;
  wire lt, rtlcn1, rtlcClkX, rtlcXXX;
  supply0 rtlcVss;
  supply1 rtlcVcc;

  msrv_soc_mux2_pv6 ltmux(
      .d0(LT), .d1(LTU), .s(BUnsigned), .y(lt)
