  msrv_soc_cnt cnt(
      .A(A), .RevA(RevA), .B(B[1:0]), .W64(W64), .CntResult(CntResult)
  );
  msrv_soc_byteop bu(
      .A(A), .ByteSelect(B[0]), .ByteResult(ByteResult)
  );
  msrv_soc_ext ext(
      .A(A[15:0]), .ExtSelect(rtlcn0), .ExtResult(ExtResult)
  );
  msrv_soc_mux2 minmaxmux(
      .d0(B), .d1(A), .s(rtlcn1), .y(MinMaxResult)
  );
