      .d0(CntResult), .d1(ExtResult), .d2(ByteResult), .d3(MinMaxResult), .s(ZBBSelect[1:0]), 
      .y(ZBBResult)
  );
  RTLC_XOR2 rtlc0_3(
      .Z(rtlcn1), .A(ZBBSelect[2]), .B(lt)
  );
  RTLC_AND2 rtlc0_4(
      .Z(rtlcn0[0]), .A(B[2]), .B(B[0])
  );
  RTLC_INV rtlc0_5(
      .Z(rtlcn0[1]), .A(B[2])
  );
endmodule

