module msrv_soc_aes64d(rs1, rs2, finalround, aes64im, result);
  input  [63:0] rs1, rs2;
  input  finalround, aes64im;
  output [63:0] result;

  wire [63:0] ShiftRowsOut, SboxOut, MixcolsIn, MixcolsOut;
  wire rtlcClkX, rtlcXXX;
  supply0 rtlcVss;
  supply1 rtlcVcc;

  msrv_soc_aesinvshiftrows64 srow(
      .a({rs2, rs1}), .y(ShiftRowsOut)
  );
  msrv_soc_aesinvsbox64 invsbox(
      .a(ShiftRowsOut), .y(SboxOut)
  );
  msrv_soc_mux2 mixcolmux(
      .d0(SboxOut), .d1(rs1), .s(aes64im), .y(MixcolsIn)
  );
  msrv_soc_aesinvmixcolumns32 invmw0(
      .a(MixcolsIn[31:0]), .y(MixcolsOut[31:0])
  );
  msrv_soc_aesinvmixcolumns32 invmw1(
      .a(MixcolsIn[63:32]), .y(MixcolsOut[63:32])
  );
  msrv_soc_mux2 resultmux(
      .d0(MixcolsOut), .d1(SboxOut), .s(finalround), .y(result)
  );
endmodule

