module msrv_soc_zknde64(A, B, round, ZKNSelect, ZKNDEResult);
  input  [63:0] A, B;
  input  [3:0] round, ZKNSelect;
  output [63:0] ZKNDEResult;

  wire [63:0] aes64dRes, aes64eRes, aes64ks1iRes, aes64ks2Res;
  wire [31:0] SboxEIn, SboxKIn, Sbox0In, Sbox0Out;
  wire rtlcXXX, rtlcClkX;
  supply0 rtlcVss;
  supply1 rtlcVcc;

  msrv_soc_aessbox32 sbox(
      .a(Sbox0In), .y(Sbox0Out)
  );
  msrv_soc_aes64ks1i aes64ks1i(
      .round(round), .rs1(A[63:32]), .Sbox0Out(Sbox0Out), .SboxKIn(SboxKIn), .result(aes64ks1iRes)
  );
  msrv_soc_aes64ks2 aes64ks2(
      .rs2(B), .rs1(A[63:32]), .result(aes64ks2Res)
  );
  msrv_soc_mux4_pv2 zkndmux(
      .d0(aes64dRes), .d1(aes64eRes), .d2(aes64ks1iRes), .d3(aes64ks2Res), .s(ZKNSelect[1:0]), 
      .y(ZKNDEResult)
  );
  msrv_soc_aes64d \genblk1.aes64d (
      .rs1(A), .rs2(B), .finalround(ZKNSelect[2]), .aes64im(ZKNSelect[3]), .result(aes64dRes)
  );
  msrv_soc_aes64e \genblk2.aes64e (
      .rs1(A), .rs2(B), .finalround(ZKNSelect[2]), .Sbox0Out(Sbox0Out), .SboxEIn(SboxEIn), 
      .result(aes64eRes)
  );
  msrv_soc_mux2_pv1 \genblk2.sboxmux (
      .d0(SboxEIn), .d1(SboxKIn), .s(ZKNSelect[1]), .y(Sbox0In)
  );
endmodule

