module msrv_soc_datapath(clk, reset, ImmSrcD, InstrD, Rs1D, Rs2D, Rs2E, PCE, PCLinkE, 
                         Funct3E, Funct7E, StallE, FlushE, ForwardAE, ForwardBE, 
                         W64E, UW64E, SubArithE, ALUSrcAE, ALUSrcBE, ALUResultSrcE, 
                         ALUSelectE, JumpE, BranchSignedE, BSelectE, ZBBSelectE, 
                         BALUControlE, BMUActiveE, CZeroE, FlagsE, IEUAdrE, ForwardedSrcAE, 
                         ForwardedSrcBE, StallM, FlushM, FWriteIntM, FCvtIntW, 
                         FIntResM, SrcAM, WriteDataM, StallW, FlushW, RegWriteW, 
                         IntDivW, SquashSCW, ResultSrcW, FCvtIntResW, ReadDataW, 
                         CSRReadValW, MDUResultW, FIntDivResultW, RdW);
  input  [63:0] PCE, PCLinkE, FIntResM, FCvtIntResW, ReadDataW, CSRReadValW, 
                MDUResultW, FIntDivResultW;
  input  [31:0] InstrD;
  input  [6:0] Funct7E;
  input  [4:0] Rs1D, Rs2D, Rs2E, RdW;
  input  [3:0] BSelectE, ZBBSelectE;
  input  [2:0] ImmSrcD, Funct3E, ALUSelectE, BALUControlE, ResultSrcW;
  input  [1:0] ForwardAE, ForwardBE, CZeroE;
  input  clk, reset, StallE, FlushE, W64E, UW64E, SubArithE, ALUSrcAE, 
         ALUSrcBE, ALUResultSrcE, JumpE, BranchSignedE, BMUActiveE, StallM, 
         FlushM, FWriteIntM, FCvtIntW, StallW, FlushW, RegWriteW, IntDivW, 
         SquashSCW;
  output [63:0] IEUAdrE, ForwardedSrcAE, ForwardedSrcBE, SrcAM, WriteDataM;
  output [1:0] FlagsE;

  wire [63:0] R1D, R2D, ImmExtD, R1E, R2E, ImmExtE, SrcAE, SrcBE, ALUResultE, 
              AltResultE, IEUResultE, IEUResultM, IFResultM, SCResultW, 
              ResultW, IFResultW, IFCvtResultW, MulDivResultW;
  wire rtlcn0, rtlcn3, rtlcn6, rtlcClkX, rtlcXXX;
  supply0 rtlcVss;
  supply1 rtlcVcc;

  msrv_soc_regfile regf(
      .clk(clk), .reset(reset), .we3(RegWriteW), .a1(Rs1D), .a2(Rs2D), .a3(RdW), 
      .wd3(ResultW), .rd1(R1D), .rd2(R2D)
  );
  msrv_soc_extend ext(
      .InstrD(InstrD[31:7]), .ImmSrcD(ImmSrcD), .ImmExtD(ImmExtD)
  );
  msrv_soc_flopenrc_pv3 RD1EReg(
      .clk(clk), .reset(reset), .clear(FlushE), .en(rtlcn0), .d(R1D), .q(R1E)
  );
  msrv_soc_flopenrc_pv3 RD2EReg(
      .clk(clk), .reset(reset), .clear(FlushE), .en(rtlcn0), .d(R2D), .q(R2E)
  );
  msrv_soc_flopenrc_pv3 ImmExtEReg(
      .clk(clk), .reset(reset), .clear(FlushE), .en(rtlcn0), .d(ImmExtD), .q(ImmExtE)
  );
  msrv_soc_mux3_pv1 faemux(
      .d0(R1E), .d1(ResultW), .d2(IFResultM), .s(ForwardAE), .y(ForwardedSrcAE)
  );
  msrv_soc_mux3_pv1 fbemux(
      .d0(R2E), .d1(ResultW), .d2(IFResultM), .s(ForwardBE), .y(ForwardedSrcBE)
  );
  msrv_soc_comparator comp(
      .a(ForwardedSrcAE), .b(ForwardedSrcBE), .sgnd(BranchSignedE), .flags(FlagsE)
  );
  msrv_soc_mux2 srcamux(
      .d0(ForwardedSrcAE), .d1(PCE), .s(ALUSrcAE), .y(SrcAE)
  );
  msrv_soc_mux2 srcbmux(
      .d0(ForwardedSrcBE), .d1(ImmExtE), .s(ALUSrcBE), .y(SrcBE)
  );
  msrv_soc_alu alu(
      .A(SrcAE), .B(SrcBE), .W64(W64E), .UW64(UW64E), .SubArith(SubArithE), .ALUSelect(ALUSelectE), 
      .BSelect(BSelectE), .ZBBSelect(ZBBSelectE), .Funct3(Funct3E), .Funct7(Funct7E), 
      .Rs2E(Rs2E), .BALUControl(BALUControlE), .BMUActive(BMUActiveE), .CZero(CZeroE), 
      .ALUResult(ALUResultE), .Sum(IEUAdrE)
  );
  msrv_soc_mux2 altresultmux(
      .d0(ImmExtE), .d1(PCLinkE), .s(JumpE), .y(AltResultE)
  );
  msrv_soc_mux2 ieuresultmux(
      .d0(ALUResultE), .d1(AltResultE), .s(ALUResultSrcE), .y(IEUResultE)
  );
  msrv_soc_flopenrc_pv3 SrcAMReg(
      .clk(clk), .reset(reset), .clear(FlushM), .en(rtlcn3), .d(SrcAE), .q(SrcAM)
  );
  msrv_soc_flopenrc_pv3 IEUResultMReg(
      .clk(clk), .reset(reset), .clear(FlushM), .en(rtlcn3), .d(IEUResultE), .q(IEUResultM)
  );
  msrv_soc_flopenrc_pv3 WriteDataMReg(
      .clk(clk), .reset(reset), .clear(FlushM), .en(rtlcn3), .d(ForwardedSrcBE), 
      .q(WriteDataM)
  );
  msrv_soc_flopenrc_pv3 IFResultWReg(
      .clk(clk), .reset(reset), .clear(FlushW), .en(rtlcn6), .d(IFResultM), .q(IFResultW)
  );
  msrv_soc_mux5 resultmuxW(
      .d0(IFCvtResultW), .d1(ReadDataW), .d2(CSRReadValW), .d3(MulDivResultW), 
      .d4(SCResultW), .s(ResultSrcW), .y(ResultW)
  );
  msrv_soc_mux2 \fpmux.resultmuxM (
      .d0(IEUResultM), .d1(FIntResM), .s(FWriteIntM), .y(IFResultM)
  );
  msrv_soc_mux2 \fpmux.cvtresultmuxW (
      .d0(IFResultW), .d1(FCvtIntResW), .s(FCvtIntW), .y(IFCvtResultW)
  );
  msrv_soc_mux2 \fpmux.genblk1.divresultmuxW (
      .d0(MDUResultW), .d1(FIntDivResultW), .s(IntDivW), .y(MulDivResultW)
  );
  RTLC_BUF rtlc0_7(
      .Z(SCResultW[0]), .A(SquashSCW)
  );
  RTLC_BUF rtlc0_8(
      .Z(SCResultW[1]), .A(1'b0)
  );
  RTLC_BUF rtlc0_9(
      .Z(SCResultW[2]), .A(1'b0)
