  wire both, IFUReqDelay, FinalBeat, FinalBeatD, BeatCntEn, BeatCntReset, 
       rtlcn0, rtlcn2, rtlcn3, rtlc0n33, rtlc0n37, rtlc0n40, rtlc0n41, 
       rtlc0n42, rtlcClkX, rtlcXXX, rtlc0n26, rtlc0n27, rtlc0_PS8_n32, rtlcn89, 
