      .clk(HCLK), .reset(rtlcn2), .en(BeatCntEn), .q(BeatCount)
  );
  msrv_soc_flopenr_pv3 FinalBeatReg(
      .clk(HCLK), .reset(rtlcn3), .en(BeatCntEn), .d(FinalBeat), .q(FinalBeatD)
  );
