module msrv_soc_fma(Xs, Ys, Zs, Xe, Ye, Ze, Xm, Ym, Zm, XZero, YZero, ZZero, OpCtrl, 
                    ASticky, Sm, InvA, As, Ps, Ss, Se, SCnt);
  input  [52:0] Xm, Ym, Zm;
  input  [10:0] Xe, Ye, Ze;
  input  [2:0] OpCtrl;
  input  Xs, Ys, Zs, XZero, YZero, ZZero;
  output [161:0] Sm;
  output [12:0] Se;
  output [7:0] SCnt;
  output ASticky, InvA, As, Ps, Ss;

  wire [161:0] Am, AmInv;
  wire [105:0] Pm, PmKilled;
  wire [12:0] Pe;
  wire KillProd, rtlcn0, rtlc0n6, rtlc0n7, rtlcClkX, rtlcXXX;
  supply0 rtlcVss;
  supply1 rtlcVcc;

  msrv_soc_fmaexpadd expadd(
      .Xe(Xe), .Ye(Ye), .XZero(XZero), .YZero(YZero), .Pe(Pe)
  );
  msrv_soc_fmamult mult(
      .Xm(Xm), .Ym(Ym), .Pm(Pm)
  );
  msrv_soc_fmasign sign(
      .OpCtrl(OpCtrl), .Xs(Xs), .Ys(Ys), .Zs(Zs), .Ps(Ps), .As(As), .InvA(InvA)
  );
  msrv_soc_fmaalign align(
      .Xe(Xe), .Ye(Ye), .Ze(Ze), .Zm(Zm), .XZero(XZero), .YZero(YZero), .ZZero(ZZero), 
      .Am(Am), .ASticky(ASticky), .KillProd(KillProd)
  );
  msrv_soc_fmaadd add(
      .Am(Am), .Ze(Ze), .Ps(Ps), .Pe(Pe), .Pm(Pm), .InvA(InvA), .KillProd(KillProd), 
      .ASticky(ASticky), .AmInv(AmInv), .PmKilled(PmKilled), .Ss(Ss), .Se(Se), 
      .Sm(Sm)
  );
  msrv_soc_fmalza lza(
      .A(AmInv), .Pm(PmKilled), .Cin(rtlcn0), .sub(InvA), .SCnt(SCnt)
  );
  RTLC_AND2 rtlc0_1(
      .Z(rtlcn0), .A(InvA), .B(rtlc0n7)
  );
  RTLC_INV rtlc0_3(
      .Z(rtlc0n6), .A(ASticky)
  );
  RTLC_OR2 rtlc_6(
      .Z(rtlc0n7), .A(rtlc0n6), .B(KillProd)
  );
endmodule

