module msrv_soc_ahbapbbridge(HCLK, HRESETn, HSEL, HADDR, HTRANS, HWSTRB, HWRITE, 
                             HREADY, HWDATA, HREADYOUT, HRDATA, HRESP, PCLK, PRESETn, 
                             PADDR, PENABLE, PSTRB, PWRITE, PWDATA, PSEL, PRDATA, 
                             PREADY);
  input  [319:0] PRDATA;
  input  [63:0] HWDATA;
  input  [55:0] HADDR;
  input  [7:0] HWSTRB;
  input  [4:0] HSEL, PREADY;
  input  [1:0] HTRANS;
  input  HCLK, HRESETn, HWRITE, HREADY, PCLK, PRESETn;
  output [63:0] HRDATA, PWDATA;
  output [55:0] PADDR;
  output [7:0] PSTRB;
  output [4:0] PSEL;
  output HREADYOUT, HRESP, PENABLE, PWRITE;

  wire [63:0] s_wdata, s_rdata;
  wire [55:0] s_addr;
  wire [7:0] s_strb;
  wire [4:0] s_sel;
  wire s_trans_valid, s_write, s_resp, s_req_h, s_req_p, s_ack_h, s_ack_p, 
       rtlcXXX, rtlcClkX;
  supply0 rtlcVss;
  supply1 rtlcVcc;

  msrv_soc_ahb_slave AHB_SLAVE(
      .HCLK(HCLK), .HRESETn(HRESETn), .HSEL(HSEL), .HADDR(HADDR), .HTRANS(HTRANS), 
      .HWRITE(HWRITE), .HWSTRB(HWSTRB), .HREADY(HREADY), .HWDATA(HWDATA), .HREADYOUT(HREADYOUT), 
      .HRDATA(HRDATA), .HRESP(HRESP), .s_addr(s_addr), .s_trans_valid(s_trans_valid), 
      .s_write(s_write), .s_strb(s_strb), .s_sel(s_sel), .s_wdata(s_wdata), .s_rdata(s_rdata), 
      .s_req_h(s_req_h), .s_ack_h(s_ack_h)
  );
  msrv_soc_synchronizer SYNCHRONIZER1(
      .clk(PCLK), .resetn(PRESETn), .enable(1'b1), .d_in(s_req_h), .d_out(s_req_p)
  );
  msrv_soc_synchronizer SYNCHRONIZER2(
      .clk(HCLK), .resetn(HRESETn), .enable(1'b1), .d_in(s_ack_p), .d_out(s_ack_h)
  );
  msrv_soc_apb_master APB_MASTER(
      .PCLK(PCLK), .PRESETn(PRESETn), .s_req_p(s_req_p), .s_ack_p(s_ack_p), .s_addr(s_addr), 
      .s_trans_valid(s_trans_valid), .s_strb(s_strb), .s_sel(s_sel), .s_write(s_write), 
      .s_wdata(s_wdata), .s_rdata(s_rdata), .PADDR(PADDR), .PENABLE(PENABLE), .PWRITE(PWRITE), 
      .PSTRB(PSTRB), .PWDATA(PWDATA), .PSEL(PSEL), .PRDATA(PRDATA), .PREADY(PREADY)
  );
endmodule

