module msrv_soc_gpio_apb(PCLK, PRESET, PRDATA, PADDR, PWDATA, PSEL, PENABLE, PWRITE, 
                         aux_in, IRQ, PREADY, out_pad_oen, out_pad_o, in_pad_i);
  input  [63:0] PWDATA;
  input  [31:0] in_pad_i;
  input  [8:0] aux_in;
  input  [7:0] PADDR;
  input  PCLK, PRESET, PSEL, PENABLE, PWRITE;
  output [63:0] PRDATA;
  output [31:0] out_pad_oen, out_pad_o;
  output IRQ, PREADY;

  wire [31:0] gpio_dat_i, gpio_dat_o;
  wire [8:0] aux_i;
  wire [7:0] gpio_adr;
  wire gpio_we, gpio_inta_o, sys_clk, sys_rst, rtlcXXX, rtlcClkX;
  supply0 rtlcVss;
  supply1 rtlcVcc;

  msrv_soc_apb_slave_interface APB_INTERFACE(
      .PADDR(PADDR), .PWDATA(PWDATA), .PCLK(PCLK), .PSEL(PSEL), .PENABLE(PENABLE), 
      .PWRITE(PWRITE), .PRESET(PRESET), .PRDATA(PRDATA), .PREADY(PREADY), .gpio_inta_o(gpio_inta_o), 
      .IRQ(IRQ), .gpio_we(gpio_we), .gpio_adr(gpio_adr), .gpio_dat_i(gpio_dat_i), 
      .gpio_dat_o(gpio_dat_o), .sys_clk(sys_clk), .sys_rst(sys_rst)
  );
  msrv_soc_aux_interface AUX_INTERFACE(
      .clk(sys_clk), .rst(sys_rst), .aux_in(aux_in), .aux_i(aux_i)
  );
  msrv_soc_gpio_register GPIO_REGISTER(
      .sys_clk(sys_clk), .sys_rst(sys_rst), .gpio_adr(gpio_adr), .gpio_we(gpio_we), 
      .gpio_dat_i(gpio_dat_i), .gpio_dat_o(gpio_dat_o), .gpio_inta_o(gpio_inta_o), 
      .in_pad_i(in_pad_i), .out_pad_o(out_pad_o), .oen_padoe_o(out_pad_oen), .aux_i(aux_i)
  );
endmodule

