      .Z(Z), .in1(tmp0), .in2(tmp1), .in3(tmp2), .in4(tmp3), .in5(tmp4), .in6(tmp5), 
      .in7(tmp6), .in8(tmp7), .in9(tmp8), .in10(tmp9), .in11(tmp10), .in12(tmp11)
  );
